"""Offline report of completed, pressure-stopped and skipped local arms."""
import json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];HERE=ROOT/'round2'
def main():
 r=json.loads((HERE/'local-rubric-jevk5-v1/results.json').read_text());e=json.loads((HERE/'local-rubric-jevk5-v1/evaluation.json').read_text());p=json.loads((HERE/'local-rubric-plan.json').read_text());q=json.loads((HERE/'local-qwen-headroom.json').read_text());stop=json.loads((ROOT/'runs/local-rubric-plumb-v1/guard-stop.json').read_text())
 assert r['forward_calls']==80 and all(x['status']=='ok' and len(x['answers'])==20 for x in r['rows'])
 assert all(a['missing_letters']==0 for x in r['rows'] for a in x['answers'])
 assert not (HERE/'local-rubric-plumb-v1/progress.json').exists() and not q['fits']
 t=[json.loads(x) for x in (ROOT/'runs/local-rubric-jevk5-v1/telemetry.jsonl').read_text().splitlines()]
 resource={'minimum_host_available_gib':min(x['host']['available_bytes'] for x in t)/2**30,'minimum_guest_available_gib':min(x['guest_available'] for x in t)/2**30,'minimum_gpu_free_mib':min(x['gpu_free_mib'] for x in t),'max_gpu_temperature_c':max(x['gpu_temp'] for x in t),'active_swap_observed':any(x['swap']!=t[0]['swap'] for x in t)}
 summary={'protocol_sha256':p['protocol_sha256'],'unit_tests_passed':67,'models':{'jevk5':'completed80localforwards','plumb':'guard_stopped_during_load_no_predictions','qwen35':'not_attempted_insufficient_conservative_loading_headroom'},'hosted_api_calls':0,'new_spend_usd':0,'shared_commitments_usd':'1.87','jevk5_resource':resource,'jevk5_input_tokens':sum(a['answer']['input_tokens'] for x in r['rows'] for a in x['answers']),'jevk5_rank20_median_seconds':statistics.median(x['wall_seconds'] for x in r['rows']),'jevk5_total_seconds_including_load':r['total_seconds_including_load'],'plumb_guard':stop,'qwen_headroom':q,'metrics':e['metrics']}
 (HERE/'LOCAL_RUBRIC_SUMMARY.json').write_text(json.dumps(summary,indent=2))
 lines=['# Local BM25 reranking diagnostic','','Local JevK5 completed 80 finite-score evaluations over two fixed public development queries, two rubrics and 20 candidates. **Recall@5/10 remained 0.75**, already the pool ceiling. The constraint rubric improved NDCG@10 from **0.521912 to 0.622038** relative to BM25/original direct scoring. This two-query exposed diagnostic is not a confirmed benchmark improvement.','',
 '| Local JevK5 arm | Recall@5 | Recall@10 | NDCG@10 |','|---|---:|---:|---:|']
 for name,v in e['metrics'].items():
  a=v['aggregate'];lines.append('| '+name+' | '+' | '.join(f'{a[k]:.6f}' for k in ['Recall@5','Recall@10','NDCG@10'])+' |')
 lines+=['','The same original/constraint rubric text, BM25 candidate pools, first two development IDs and stable retrieval-order ties were fixed before local inference. The existing native JevK5/SemIf four-option prompt and log-probability readout were used; the previously configured JevK5 Q5 temperature 1.22 was retained, not tuned on SkillRet. All 80 decisions contained every required option letter in the top256 token log-probabilities, so no probability-floor approximation was used. Model SHA256 and local adapter source hashes are pinned in the manifest. Hosted TypeSafe Jev and this local JevK5 model are different systems.','',
 '## Resource feasibility and remaining work','','- **JevK5 Q5:** completed, 80/80 decisions valid, four complete query/rubric rankings.','- **Plumb Q4:** stopped by the resource guard during loading, before any prediction was saved. Windows available RAM was 2,129,534,976 bytes, below the unchanged 2GiB reserve. No retry. This is a feasibility failure, not measured retrieval quality.','- **Qwen3.5 Q4:** not loaded. After the Plumb pressure event, a conservative loading check required the model bytes plus 2GiB reserve and 128MiB staging overhead. Available host memory was '+f"{q['telemetry']['host']['available_bytes']/2**30:.3f}GiB versus {q['conservative_host_required_bytes']/2**30:.3f}GiB required."+' No retry, limit relaxation, unrelated process termination or download.','',
 'All requested local models have an explicit execution status. Plumb and Qwen have no quality score; substituting a zero quality score would conflate resource availability with model accuracy. The complete failed-load guard log is preserved. Further local comparison needs more idle host RAM while keeping the same WSL limits, or a separately designed smaller workload; no such follow-up was silently launched.','',
 f"JevK5 median wall time per 20-candidate rubric ranking: {summary['jevk5_rank20_median_seconds']:.3f}s. Input tokens across 80 pointwise decisions: {summary['jevk5_input_tokens']:,}. Total including model hash verification, startup, inference and shutdown: {r['total_seconds_including_load']:.3f}s. Cached BM25 retrieval is excluded. This differs from hosted multi-question batching, so no direct speedup ratio is claimed.", '',
 f"During the completed run: host minimum available {resource['minimum_host_available_gib']:.3f}GiB, guest {resource['minimum_guest_available_gib']:.3f}GiB, GPU minimum free {resource['minimum_gpu_free_mib']}MiB, GPU maximum {resource['max_gpu_temperature_c']}C; no active swap observed. Guard samples cover host/guest/GPU reserves. Client-process RSS does not represent full server memory and is not used as model memory. WSL stays 6GiB RAM / 2 CPUs / 2GiB swap; llama.cpp uses one CPU thread and direct-I/O loading.", '',
 '## Validation, cost and reproduction','','67 offline tests pass, including finite answers, mock answer-order mapping, stable ranking, local endpoint restriction and maximum local-forward/context bounds. No external API, saved-key access, model upload or download was required by this diagnostic. New spend is zero; shared commitments remain USD1.87 after the separately approved hosted screen.','',
 'The one-shot local runner is `round2/local_rubric_screen.py`; completed/stopped output paths reject reruns. Offline report regeneration: `.venv/bin/python round2/report_local_rubrics.py`. Tests: `.venv/bin/python -m unittest discover -s round2 -p "test_*.py"`. Run from `/home/user/code/mia5150-local`.','',
 'The six-query hosted screen report is `round2/VARIED_SCREEN_RESULTS.md`. These two-query local metrics must not be merged with the six-query hosted summary or the earlier dense-retrieval confirmation.','',f"Local protocol SHA256: `{p['protocol_sha256']}`."]
 (HERE/'LOCAL_RUBRIC_RESULTS.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps({k:v for k,v in summary.items() if k not in ['metrics','qwen_headroom']},indent=2))
if __name__=='__main__':main()
